from z3 import *

# Houses are numbered 1..2
houses = [1, 2]

# Attribute variables: each maps attribute -> house number
name = {
    'Eric': Int('name_Eric'),
    'Arnold': Int('name_Arnold')
}
phone = {
    'iphone 13': Int('phone_iphone13'),
    'samsung galaxy s21': Int('phone_samsung')
}
drink = {
    'water': Int('drink_water'),
    'tea': Int('drink_tea')
}
sport = {
    'basketball': Int('sport_basketball'),
    'soccer': Int('sport_soccer')
}

s = Solver()

# Domain constraints: each variable must be 1 or 2
for var_dict in (name, phone, drink, sport):
    for v in var_dict.values():
        s.add(Or(v == 1, v == 2))

# Distinctness within each category
s.add(Distinct(*name.values()))
s.add(Distinct(*phone.values()))
s.add(Distinct(*drink.values()))
s.add(Distinct(*sport.values()))

# Clues
s.add(name['Arnold'] == 2)                               # 1
s.add(phone['samsung galaxy s21'] != 1)                 # 2
s.add(name['Eric'] == sport['soccer'])                   # 3
s.add(phone['samsung galaxy s21'] == drink['tea'])      # 4

# Solve
if s.check() == sat:
    m = s.model()
    # Build reverse look‑ups: house -> attribute
    house_info = {h: {} for h in houses}
    for attr, var in name.items():
        house = m[var].as_long()
        house_info[house]['Name'] = attr
    for attr, var in phone.items():
        house = m[var].as_long()
        house_info[house]['Phone'] = attr
    for attr, var in drink.items():
        house = m[var].as_long()
        house_info[house]['Drink'] = attr
    for attr, var in sport.items():
        house = m[var].as_long()
        house_info[house]['Sport'] = attr

    # Print in order
    for h in sorted(house_info):
        info = house_info[h]
        print(f"House {h}: {info['Name']}, {info['Phone']}, {info['Drink']}, {info['Sport']}")
else:
    print("No solution found")

from z3 import *

# Enumerations
names = {"Arnold": 0, "Peter": 1, "Eric": 2}
lunches = {"spaghetti": 0, "grilled cheese": 1, "pizza": 2}
colors = {"yellow": 0, "white": 1, "red": 2}

# Reverse maps for printing
rev_names = {v: k for k, v in names.items()}
rev_lunches = {v: k for k, v in lunches.items()}
rev_colors = {v: k for k, v in colors.items()}

# Variables for three houses (indices 0,1,2 correspond to House 1,2,3)
name = [Int(f"name_{i}") for i in range(3)]
lunch = [Int(f"lunch_{i}") for i in range(3)]
color = [Int(f"color_{i}") for i in range(3)]

s = Solver()

# Domain constraints
for i in range(3):
    s.add(And(name[i] >= 0, name[i] <= 2))
    s.add(And(lunch[i] >= 0, lunch[i] <= 2))
    s.add(And(color[i] >= 0, color[i] <= 2))

# All-different constraints within each category
s.add(Distinct(name))
s.add(Distinct(lunch))
s.add(Distinct(color))

# Clue 5: The person who loves the spaghetti eater is Eric.
for i in range(3):
    s.add(Implies(lunch[i] == lunches["spaghetti"], name[i] == names["Eric"]))

# Clue 2: The person who loves spaghetti also loves yellow (same person)
for i in range(3):
    s.add(Implies(lunch[i] == lunches["spaghetti"], color[i] == colors["yellow"]))
    s.add(Implies(color[i] == colors["yellow"], lunch[i] == lunches["spaghetti"]))

# Clue 4: Peter is directly left of the person who loves spaghetti.
for i in range(3):
    if i < 2:  # houses 1 and 2 have a house to the right
        s.add(Implies(name[i] == names["Peter"], lunch[i + 1] == lunches["spaghetti"]))
    else:      # house 3 cannot be left of anyone
        s.add(name[i] != names["Peter"])

# Clue 1: Red and Yellow are neighbors (different houses)
for i in range(3):
    if i == 0:
        s.add(Implies(color[i] == colors["red"], color[i + 1] == colors["yellow"]))
    elif i == 2:
        s.add(Implies(color[i] == colors["red"], color[i - 1] == colors["yellow"]))
    else:
        s.add(Implies(color[i] == colors["red"],
                      Or(color[i - 1] == colors["yellow"], color[i + 1] == colors["yellow"])))

# Clue 3: Pizza lover and Red are neighbors (different houses)
for i in range(3):
    if i == 0:
        s.add(Implies(lunch[i] == lunches["pizza"], color[i + 1] == colors["red"]))
    elif i == 2:
        s.add(Implies(lunch[i] == lunches["pizza"], color[i - 1] == colors["red"]))
    else:
        s.add(Implies(lunch[i] == lunches["pizza"],
                      Or(color[i - 1] == colors["red"], color[i + 1] == colors["red"])))

# Solve
if s.check() == sat:
    m = s.model()
    for i in range(3):
        n = rev_names[m[name[i]].as_long()]
        l = rev_lunches[m[lunch[i]].as_long()]
        c = rev_colors[m[color[i]].as_long()]
        print(f"House {i+1}: {n}, {l}, {c}")
else:
    print("No solution found.")
